import shutil,subprocess,sys,json,os,glob
from pathlib import Path
P={
 'rounding':('spokehouse/fares.py','return seconds // 60','return -(-seconds // 60)'),
 'retention':('spokehouse/jobs/compact.py','timedelta(hours=','timedelta(days='),
 'timecmp':('spokehouse/jobs/holds.py','hold["until"] <= fmt_ts(now)','parse_ts(hold["until"]) <= now'),
 'stale':('spokehouse/store.py','    out = data(state)\n','    if load(path)["meta"]["rev"] != state["meta"]["rev"]:\n        raise StaleState(path)\n    out = data(state)\n'),
}
def build(name,fixes):
    root=Path('/tmp/w/v_'+name)
    shutil.rmtree(root,ignore_errors=True)
    root.mkdir()
    shutil.copytree('/app/tools',root/'tools'); shutil.copytree('/app/feeds',root/'feeds')
    shutil.copytree('/tmp/w/orig_pkg',root/'spokehouse')
    for f in fixes:
        fn,a,b=P[f]; p=root/fn; t=p.read_text(); assert a in t; p.write_text(t.replace(a,b))
    (root/'var/snapshots').mkdir(parents=True)
    shutil.copy('/app/var/snapshots/004239-20270327T140508Z-holds.json',root/'var/state.json')
    out=subprocess.run([sys.executable,'tools/sched.py','timeline','/tmp/w/sched.json','--root',str(root)],cwd=root,capture_output=True,text=True)
    (root/'log.txt').write_text(out.stdout+out.stderr)
    return root
def data(p):
    d=json.load(open(p)); d.pop('meta'); return d
if __name__=='__main__':
    base=build('base',[])
    diffs=[]
    for f in sorted(glob.glob('/app/var/snapshots/*')):
        n=os.path.basename(f)
        if n<'004240': continue
        b=base/'var/snapshots'/n
        if not b.exists() or data(b)!=data(f): diffs.append(n)
    print('base mismatches',len(diffs),diffs[:5])
    for k in P:
        r=build(k,[k]); bad=[]
        for f in sorted(glob.glob('/app/var/snapshots/*')):
            n=os.path.basename(f)
            if n<'004240' or 'admin' in n: continue
            # compare by run: variant snapshot at same job/time
            pass
        res={}
        # map by (job, at) suffix
        key=lambda n:n.split('-',1)[1]
        vs={key(os.path.basename(x)):x for x in glob.glob(str(r/'var/snapshots/*'))}
        bs={key(os.path.basename(x)):x for x in glob.glob(str(base/'var/snapshots/*'))}
        ch=[]
        for kk,x in sorted(bs.items()):
            if 'admin' in kk: continue
            if kk not in vs or data(vs[kk])!=data(x): ch.append(os.path.basename(x))
        json.dump(ch,open(f'/tmp/w/res_{k}.json','w'))
        print(k,len(ch),ch[:2], open(r/'log.txt').read().count('retry'))
